section.programlisting:
; A disc of points inside a ring of points: no line parts them, so one
; neuron given x and y cannot learn it. Given x² and y² instead, it can --
; in those inputs the disc and the ring lie on two sides of a line.
define Point(x: f64, y: f64, kind: f64)

function shown(v: f64) returns f64
{
    (v * 1000.0).round_even() / 1000.0
}

; The neuron's two inputs at a point: x and y, or their squares.
function inputs(p: Point, squared: bool) returns (f64, f64)
{
    if squared: (p.x * p.x, p.y * p.y) else (p.x, p.y)
}

procedure train(points: Array[Point], squared: bool)
{
    let n points.length as f64
    var w1 0.0
    var w2 0.0
    var b 0.0
    var step 0
    while step <= 400
    {
        var loss 0.0
        var right 0
        var g1 0.0
        var g2 0.0
        var gb 0.0
        for p in points
        {
            let (u, v) inputs(p, squared)
            let a tanh(w1 * u + w2 * v + b)
            let e a - p.kind
            loss := loss + 0.5 * e * e
            if a * p.kind > 0.0
                right := right + 1
            let dz e * (1.0 - a * a)
            g1 := g1 + dz * u
            g2 := g2 + dz * v
            gb := gb + dz
        }
        if step % 100 = 0
            print "  step `step`: loss `shown(loss / n)`, `right` of 16 right"
        w1 := w1 - 0.1 * g1 / n
        w2 := w2 - 0.1 * g2 / n
        b := b - 0.1 * gb / n
        step := step + 1
    }
}

; eight points on a circle of radius 1, eight on one of radius 3
var points Array[Point]()
var k 0
while k < 8
{
    let t 0.7853981633974483 * (k as f64)
    points.add(Point(cos(t), sin(t), 1.0))
    points.add(Point(3.0 * cos(t + 0.4), 3.0 * sin(t + 0.4), 0.0 - 1.0))
    k := k + 1
}
print "given x and y:"
train(points, false)
print "given x² and y²:"
train(points, true)

; XOR: the kind is +1 where x and y have the same sign, -1 where not. No ; line parts the kinds, and no single neuron learns it -- but three neurons ; in a hidden layer, and one more that reads them, do. Learning them takes ; the error back through both layers: backpropagation, written out by hand. define Point(x: f64, y: f64, kind: f64) define HIDDEN int 3
function shown(v: f64) returns f64 { (v * 1000.0).round_even() / 1000.0 }
var points Array[Point]() points.add(Point(1.0, 1.0, 1.0)) points.add(Point(0.0 - 1.0, 0.0 - 1.0, 1.0)) points.add(Point(1.0, 0.0 - 1.0, 0.0 - 1.0)) points.add(Point(0.0 - 1.0, 1.0, 0.0 - 1.0)) let n points.length as f64
; the hidden layer: neuron j has the weights w[2j] for x and w[2j+1] for y, ; and the bias c[j]; the output neuron has the weights v[j] and the bias b var w Vector[f64](2 * HIDDEN) var c Vector[f64](HIDDEN) var v Vector[f64](HIDDEN) var b 0.0 w.put(0, 0.5) w.put(1, 0.0 - 0.4) w.put(2, 0.3) w.put(3, 0.8) w.put(4, 0.0 - 0.7) w.put(5, 0.2) var k 0 var j 0 while j < HIDDEN { c.put(j, 0.0) v.put(j, 0.3 - 0.2 * (j as f64)) j := j + 1 }
; the gradients, and what each hidden neuron answers var gw Vector[f64](2 * HIDDEN) var gc Vector[f64](HIDDEN) var gv Vector[f64](HIDDEN) var h Vector[f64](HIDDEN) let rate 0.5 var step 0 while step <= 300 { k := 0 while k < 2 * HIDDEN { gw.put(k, 0.0) k := k + 1 } j := 0 while j < HIDDEN { gc.put(j, 0.0) gv.put(j, 0.0) j := j + 1 } var gb 0.0 var loss 0.0 var right 0 for p in points { ; forward: the hidden layer, then the output var z b j := 0 while j < HIDDEN { h.put(j, tanh(w[2 * j] * p.x + w[2 * j + 1] * p.y + c[j])) z := z + v[j] * h[j] j := j + 1 } let a tanh(z) let e a - p.kind loss := loss + 0.5 * e * e if a * p.kind > 0.0 right := right + 1 ; back: the output neuron's share of the error ... let d e * (1.0 - a * a) gb := gb + d j := 0 while j < HIDDEN { gv.put(j, gv[j] + d * h[j]) ; ... and each hidden neuron's, through the weight that reads it let dj d * v[j] * (1.0 - h[j] * h[j]) gw.put(2 * j, gw[2 * j] + dj * p.x) gw.put(2 * j + 1, gw[2 * j + 1] + dj * p.y) gc.put(j, gc[j] + dj) j := j + 1 } } if step % 50 = 0 print "step `step`: loss `shown(loss / n)`, `right` of 4 right" ; every weight a little against its gradient k := 0 while k < 2 * HIDDEN { w.put(k, w[k] - rate * gw[k] / n) k := k + 1 } j := 0 while j < HIDDEN { c.put(j, c[j] - rate * gc[j] / n) v.put(j, v[j] - rate * gv[j] / n) j := j + 1 } b := b - rate * gb / n step := step + 1 }
